excels.excel:

EXPORT WITH SHEET="门店销售自助分析报表", HEADER=true,
    MAPPING={"a":"门店","b":"主营品类","c":"销售额","d":"成本","e":"毛利","f":"毛利率","g":"销售占比"},
    FORMAT={"c":"#,##0","d":"#,##0","e":"#,##0","f":"0.00%","g":"0.00%"},
    FORMULAS={
        E2:'C2-D2',F2:'E2/C2',G2:'C2/C7',
        E3:'C3-D3',F3:'E3/C3',G3:'C3/C7',
        E4:'C4-D4',F4:'E4/C4',G4:'C4/C7',
        E5:'C5-D5',F5:'E5/C5',G5:'C5/C7',
        E6:'C6-D6',F6:'E6/C6',G6:'C6/C7',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'C7-D7',F7:'E7/C7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
